function dump(n,d){
  let s="  ".repeat(d)+n.type+" \""+n.name+"\" "+n.id;
  if(n.type==="TEXT") s+=" = "+JSON.stringify(n.characters);
  if(n.type==="INSTANCE") s+=" ->"+n.mainComponent.name;
  s+=" @"+Math.round(n.x)+","+Math.round(n.y)+" "+Math.round(n.width)+"x"+Math.round(n.height);
  let out=[s];
  if("children" in n) for(const c of n.children) out=out.concat(dump(c,d+1));
