function d(n,dep){
  let s="  ".repeat(dep)+n.type+" \""+n.name+"\" "+n.id;
  if(n.type==="TEXT")s+=" ="+JSON.stringify(n.characters)+" fs"+n.fontSize+" "+n.fontName.style;
  if(n.type==="INSTANCE")s+=" ->"+n.mainComponent.name;
  s+=" @"+Math.round(n.x)+","+Math.round(n.y)+" "+Math.round(n.width)+"x"+Math.round(n.height);
  if(n.layoutMode&&n.layoutMode!=="NONE")s+=" LM="+n.layoutMode+" g"+n.itemSpacing+" p["+n.paddingTop+","+n.paddingRight+","+n.paddingBottom+","+n.paddingLeft+"] "+n.primaryAxisSizingMode+"/"+n.counterAxisSizingMode;
  if(n.fills&&n.fills.length&&n.type!=="TEXT")s+=" fill="+(n.fills[0].type==="SOLID"?JSON.stringify(n.fills[0].color):n.fills[0].type);
  let o=[s];if("children" in n&&dep<2)for(const c of n.children)o=o.concat(d(c,dep+1));return o;
}
let res=["FRAME fills="+JSON.stringify(f.fills)+" clips="+f.clipsContent];
res=res.concat(d(f,0));
return res.join("\n");

